  parameters: TSchema  // TypeBox schema
  execute: (params: any) =&gt; Promise&lt;ToolResult&gt;
  render?: (params: any) =&gt; string  // TUI 渲染
}

4 Agent 循环
Agent 循环是 pi 的核心。下图展示了从用户输入到响应的完整流程：





flowchart TD
    A[用户输入] --&gt; B[prompt text]
    B --&gt; C{扩展命令?}
    C --&gt;|是| D[处理 /command]
    C --&gt;|否| E{技能模板?}
    E --&gt;|是| F[展开 /skill:name]
    E --&gt;|否| G[调用 agent.prompt]
    D --&gt; G
    F --&gt; G
    G --&gt; H[流式 LLM 响应]
    H --&gt; I{工具调用?}
    I --&gt;|是| J[执行工具]
    J --&gt; K[消息持久化]
    K --&gt; H
    I --&gt;|否| L[后处理]
    L --&gt; M{需要压缩?}
    M --&gt;|是| N[执行压缩]
    M --&gt;|否| O[返回响应]
    N --&gt; O







4.1 主循环流程
让我们深入分析 AgentSession.prompt() 的实现：
// packages/coding-agent/src/core/agent-session.ts
async prompt(text: string, options?: PromptOptions) {
  // 1. 处理扩展命令（/command）
  // 2. 发射 input 事件供扩展拦截
  // 3. 展开技能命令（/skill:name）
  // 4. 展开提示模板
  // 5. 如果正在流式处理，排队等待
  // 6. 验证模型和 API 密钥
  // 7. 构建消息数组
  // 8. 发射 before_agent_start 事件
  // 9. 调用 _runAgentPrompt()
}


4.2 核心循环
// packages/coding-agent/src/core/agent-session.ts
private async _runAgentPrompt(messages: Message[]) {
  // 核心循环
  await this.agent.prompt(messages)

  // 后处理：重试和压缩检查
  while (await this._handlePostAgentRun()) {
    await this.agent.continue()
  }
}






Tip



这个设计非常巧妙：核心循环只负责调用 LLM 和执行工具，而重试、压缩等复杂逻辑都在后处理中完成。这保持了核心循环的简洁性。




4.3 后处理逻辑
// packages/coding-agent/src/core/agent-session.ts
private async _handlePostAgentRun(): Promise&lt;boolean&gt; {
  // 1. 检查可重试错误（自动重试并退避）
  // 2. 检查是否需要压缩（上下文溢出或阈值）
  // 3. 返回 true 继续循环，false 退出
}

4 关键 API

4.1 SingleEndModifier
自定义处理逻辑的核心基类：
# cutadapt/modifiers.py
class SingleEndModifier(ABC):
    @abstractmethod
    def __call__(self, read: SequenceRecord, info: ModificationInfo) -&gt; SequenceRecord
实现要点：接收一条 read，返回处理后的 read。不能返回 None（消费 read 是 Sink 的职责）。
cutadapt 内置的 modifier 例子：
# 无条件截取前 N 个碱基
class UnconditionalCutter(SingleEndModifier):
    def __call__(self, read, info):
        return read[self.start:self.stop]


4.2 SingleEndSink
Pipeline 的最终 step，负责写入输出：
# cutadapt/steps.py
class SingleEndSink(SingleEndStep):
    def __call__(self, read, info):
        self.writer.write(read)    # 写入
        return None                 # 消费 read


4.3 OutputFiles
管理输出文件的写入。关键在于 proxied 参数：
outfiles = OutputFiles(
    proxied=cores &gt; 1,
    qualities=runner.input_file_format().has_qualities(),
    file_opener=file_opener,
    interleaved=False,
)
writer = outfiles.open_record_writer(output_path)
当 proxied=True（多进程模式），open_record_writer() 返回 ProxyRecordWriter。它内部用 BytesIO 缓冲写入内容，主进程通过 proxy_files().drain() 回收并写入实际文件。这样 worker 进程不需要直接操作文件句柄。


4.4 make_runner
工厂函数，根据核心数选择串行或并行 runner：
# cutadapt/runners.py
def make_runner(inpaths, cores, buffer_size=None):
    if cores &gt; 1:
        return ParallelPipelineRunner(inpaths, n_workers=cores, ...)
    else:
        return SerialPipelineRunner(inpaths.open())

7 扩展思路
理解了这个框架后，可以很方便地扩展其他处理逻辑：
添加质量过滤：实现一个 SingleEndStep，不满足质量阈值时返回 None 丢弃 read：
class QualityFilter(SingleEndStep):
    def __call__(self, read, info):
        avg_quality = sum(ord(c) - 33 for c in read.qualities) / len(read.qualities)
        if avg_quality &lt; self.min_quality:
            return None  # 丢弃
        return read
多个 modifier 和 step 可以自由组合到同一个 pipeline 中，cutadapt 会按顺序执行。
